    int? rotateBytes,
    int? hardCapBytes,
  }) {
    return JsonlSessionStorage._(
      _fs,
      _filePath,
      _header!,
      [..._entries],
      _currentLeafId,
      quarantined: _quarantinedEntries,
      ioRetry: _ioRetry,
