  static Future<JsonlSessionStorage> open(
    FileSystem fs,
    String filePath, {
    SessionParseExecutor? parseExecutor,
    SessionIoRetryConfig ioRetry = const SessionIoRetryConfig(),
    SessionTimingLogger? timingLog,
