      root,
      op: op,
      path: path,
      sessionId: sessionId,
      actor: actor,
      result: 'copy-delete',
    );
    final bytes = _fsOrThrow(
      await _fs.readBinaryFile(path),
      'Failed to read session $path for the trash copy',
    );
    _fsOrThrow(
      await _fs.writeBinaryFile(trashPath, bytes),
      'Failed to write trash copy $trashPath',
