    if (nonEmpty > 1) continue;
    final id = _sessionIdFromPath(path);
    if (id != null && live.containsKey(id)) continue;
    await _softDelete(

      op: op,
      path: path,
      sessionId: sessionId,
      actor: actor,
      result: 'remove-fallback',
    );
