      await _fs.remove(path, force: true),
      'Failed to delete session $path',
    );
    await _verifyGone(path);
    return;
  }
  final trashDir = _fsOrThrow(
    await _fs.joinPath([root, trashDirName]),
    'Failed to resolve trash directory',
  );
