  final forkedEntries = await _entriesToFork(
    sourceSession.getStorage(),
    entryId,
    position,
  );
  final sessionId = id ?? createSessionId();
  final createdAt = DateTime.now();
  final sessionsRoot = await _getSessionsRoot();
