        config: ioRetry,
      ),
      'Failed to create session $filePath',
    );
  });
  return JsonlSessionStorage._(
    fs,
    filePath,
    header,
    [],
    null,
    ioRetry: ioRetry,
    headerLine: jsonEncode(header.toJson()),
  );
}

