    cwd: cwd,
    sessionId: sessionId,
    parentSessionPath: parentSessionPath ?? source.path,
    metadata: metadata ?? source.metadata,
    ioRetry: _ioRetry,
  );
  for (final entry in forkedEntries) {
    await storage.appendEntry(entry);
  }
  return Session(storage);
}

