        final id = (entry.data as Map?)?['id'];
        if (id is String) consumedIds.add(id);
      }
    }
    return [
      for (final id in pendingIds)
        if (!consumedIds.contains(id) && texts[id]!.isNotEmpty)
          (recordId: id, text: texts[id]!),
    ];
  } on Object {
    return const [];

